"""Check same-prefix causal parity and time the two preparation routes on one GPU."""
import json
import statistics
import sys
from pathlib import Path
from time import perf_counter_ns

import torch

from bio_inspired_nanochat.engine import Engine, KVCache
from bio_inspired_nanochat.gpt import GPT, GPTConfig
from bio_inspired_nanochat.gpt_synaptic import GPTSynaptic, GPTSynapticConfig
from bio_inspired_nanochat.synaptic import SynapticConfig

ATOL = RTOL = 1e-4
STEPS = 16


def logits(engine, tokens, cache):
    value = engine._forward(tokens, cache)
    return value[0] if isinstance(value, tuple) else value


def prepare(engine, tokens, start, route):
    reset = getattr(engine.model, "reset_sequence_state", None)
    if reset is not None:
        reset()
    cfg = engine.model.config
    cache = KVCache(tokens.shape[0], cfg.n_kv_head, tokens.shape[1], cfg.n_embd // cfg.n_head, cfg.n_layer)
    if route == "single":
        prefill = logits(engine, tokens[:, :start], cache)
    else:
        parts = [logits(engine, tokens[:, :16], cache)]
        for pos in range(16, start):
            parts.append(logits(engine, tokens[:, pos:pos+1], cache))
        prefill = torch.cat(parts, dim=1)
    assert cache.pos == start
    return cache, prefill


def snapshot(cache):
    output = {"kv": cache.kv_cache[:, :, :, :, :cache.pos, :].clone()}
    for idx, state in enumerate(cache.presyn_state or []):
        for name, value in state.items():
            for j, leaf in enumerate(value if isinstance(value, list) else [value]):
                output[f"layer_{idx}.{name}.{j}"] = leaf.clone()
    return output


def errors(expected, observed):
    assert expected.shape == observed.shape
    assert bool(torch.isfinite(expected).all()) and bool(torch.isfinite(observed).all())
    return {
        "elements": expected.numel(),
        "out_of_tolerance": int((~torch.isclose(expected, observed, rtol=RTOL, atol=ATOL)).sum()),
        "unequal": int((expected != observed).sum()),
        "max_abs": float((expected - observed).abs().max()),
    }


def state_errors(expected, observed):
    assert expected.keys() == observed.keys()
    return {key: errors(expected[key], observed[key]) for key in expected}


def continuation(engine, tokens, pos, mode, cache):
    fed = []
    outputs = []
    token = tokens[:, pos:pos+1]
    for i in range(pos, tokens.shape[1]):
        if mode == "forced":
            token = tokens[:, i:i+1]
        fed.append(token)
        output = logits(engine, token, cache)
        outputs.append(output)
        if mode == "greedy":
            token = output[:, -1, :].argmax(dim=-1, keepdim=True)
    return torch.cat(outputs, dim=1), torch.cat(fed, dim=1)


def build(backend, shape):
    batch, length, kv, delay = shape
    args = dict(sequence_len=length + STEPS, vocab_size=128, n_layer=2, n_head=4,
                n_kv_head=kv, n_embd=64)
    torch.manual_seed(64321)
    if backend == "vanilla":
        model = GPT(GPTConfig(**args))
    else:
        cfg = SynapticConfig(native_presyn=True, native_genetics=True, endo_delay=delay)
        model = GPTSynaptic(GPTSynapticConfig(**args, syn_cfg=cfg))
    return Engine(model.to("cuda").eval(), tokenizer=None)


def input_ids(shape, seed):
    batch, length, _, _ = shape
    rng = torch.Generator(device="cuda").manual_seed(seed)
    return torch.randint(0, 128, (batch, length + STEPS), device="cuda", generator=rng)


def paired(engine, tokens, length, put_single_first):
    order = ["staged", "single"][::(-1 if put_single_first else 1)]
    result = {}
    for route in order:
        torch.cuda.synchronize()
        started = perf_counter_ns()
        cache, prefill = prepare(engine, tokens, length, route)
        torch.cuda.synchronize()
        result[route] = (cache, prefill, perf_counter_ns() - started)
    return result


def parity(backend, shape, seeds):
    engine = build(backend, shape)
    length = shape[1]
    cases = []
    for i, seed in enumerate(seeds):
        tokens = input_ids(shape, seed)
        for route in ("staged", "single"):
            if i == 0:
                warm, _ = prepare(engine, tokens, length, route)
                continuation(engine, tokens, length, "forced", warm)
        result = paired(engine, tokens, length, i % 2 == 1)
        a, a_logits, a_ns = result["staged"]
        b, b_logits, b_ns = result["single"]
        prefix = state_errors(snapshot(a), snapshot(b))
        a_tail, _ = continuation(engine, tokens, length, "forced", a)
        b_tail, _ = continuation(engine, tokens, length, "forced", b)
        tail = state_errors(snapshot(a), snapshot(b))
        a, _ = prepare(engine, tokens, length, "staged")
        b, _ = prepare(engine, tokens, length, "single")
        _, a_ids = continuation(engine, tokens, length, "greedy", a)
        _, b_ids = continuation(engine, tokens, length, "greedy", b)
        row = {"seed": seed, "staged_prefill_ns": a_ns, "single_prefill_ns": b_ns,
               "prefix_logits": errors(a_logits, b_logits), "prefix_state": prefix,
               "forced_logits": errors(a_tail, b_tail), "forced_final_state": tail,
               "greedy_positions": a_ids.numel(), "greedy_token_mismatches": int((a_ids != b_ids).sum())}
        cases.append(row)
        print(json.dumps({"arm": backend, "shape":shape, "seed":seed,
                          "prefix_outside": row["prefix_logits"]["out_of_tolerance"],
                          "prefix_state_outside": sum(v["out_of_tolerance"] for v in prefix.values()),
                          "forced_outside": row["forced_logits"]["out_of_tolerance"],
                          "greedy_mismatches": row["greedy_token_mismatches"]}), flush=True)
    return cases


def timing(shape):
    engines = {arm: build(arm, shape) for arm in ("vanilla", "synaptic")}
    length = shape[1]
    for engine in engines.values():
        paired(engine, input_ids(shape, 64390), length, False)
    rows = []
    for i, seed in enumerate(range(64391, 64399)):
        tokens = input_ids(shape, seed)
        order = tuple(engines)[::(-1 if i % 2 else 1)]
        arms = {}
        for j, arm in enumerate(order):
            rounds = paired(engines[arm], tokens, length, (i + j) % 2 == 1)
            arms[arm] = {name: round_data[2] for name, round_data in rounds.items()}
        rows.append({"seed": seed, "timing_ns": arms})
    comparison = {
        arm: {
            "median_paired_latency_improvement": statistics.median(
                1.0 - row["timing_ns"][arm]["single"] / row["timing_ns"][arm]["staged"] for row in rows
            ),
            "single_wins": sum(row["timing_ns"][arm]["single"] < row["timing_ns"][arm]["staged"] for row in rows),
            **{route + "_median_ns": statistics.median(row["timing_ns"][arm][route] for row in rows)
               for route in ("single", "staged")},
        }
        for arm in engines
    }
    return {"shape": shape, "rows": rows, "comparison": comparison}


def main():
    shapes = [(1, 36, 4, 3), (2, 96, 2, 0), (1, 137, 1, 1)]
    with torch.inference_mode():
        report = {
            "tolerances": {"atol": ATOL, "rtol": RTOL},
            "shape_fields": ["batch", "prefix_tokens", "kv_heads", "delay_depth"],
            "parity": [
                {"shape": shape, "arm": arm,
                 "cases": parity(arm, shape, [64361 + i*4, 64362 + i*4, 64363 + i*4])}
                for i, shape in enumerate(shapes) for arm in ("vanilla", "synaptic")
            ],
            "timing": timing(shapes[0]),
        }
    with Path(sys.argv[1]).open("x", encoding="utf-8") as stream:
        json.dump(report, stream, indent=2, sort_keys=True, allow_nan=False)
        stream.write("\n")
    print(json.dumps(report["timing"]["comparison"], sort_keys=True))


if __name__ == "__main__":
    main()
